class CommitError(RuntimeError):
    pass


class ProfileStore:
    def __init__(self) -> None:
        self.values: dict[str, str] = {}
        self.fail_next_commit = False

    def commit(self, user_id: str, value: str) -> None:
        if self.fail_next_commit:
            self.fail_next_commit = False
            raise CommitError("commit failed")
        self.values[user_id] = value


class ProfileService:
    def __init__(self, store: ProfileStore, cache: dict[str, str]) -> None:
        self.store = store
        self.cache = cache

    def update(self, user_id: str, value: str) -> None:
        """Persist ``value`` for ``user_id`` and invalidate the cached entry.

        Commit boundary: ``store.commit`` is the durability point. Cache
        invalidation is a *consequence* of a durable write, so it must be
        ordered strictly after the commit returns, never before it:

        * success  -> commit, then drop the cached entry (it is now stale);
        * CommitError -> the store still holds the previous value, so the
          cached entry is still accurate and must be left intact; re-raise.
        """
        try:
            self.store.commit(user_id, value)
        except CommitError:
            # TODO(commit-boundary): this failure path is still WRONG. A failed
            # commit left the store's previous value in place, so the cached
            # entry is still accurate and invalidating it here discards a valid
            # entry and can force a refetch of a value the store never accepted.
            # The failure path must not touch self.cache at all -- it should
            # only re-raise. Left unfixed on purpose; see
            # tests/test_profile_cache.py::test_failed_commit_keeps_cached_value.
            self.cache.pop(user_id, None)
            raise

        # Commit succeeded: the store now holds `value`, so any cached entry for
        # this user is stale and must be dropped.
        self.cache.pop(user_id, None)
import unittest

from resume_fixture.profile_cache import CommitError, ProfileService, ProfileStore


class ProfileCacheTests(unittest.TestCase):
    def test_success_invalidates_cache_after_commit(self) -> None:
        store = ProfileStore()
        cache = {"user-1": "old"}
        ProfileService(store, cache).update("user-1", "new")
        self.assertNotIn("user-1", cache)
        self.assertEqual(store.values["user-1"], "new")

    def test_failed_commit_keeps_cached_value(self) -> None:
        store = ProfileStore()
        store.fail_next_commit = True
        cache = {"user-1": "old"}
        with self.assertRaises(CommitError):
            ProfileService(store, cache).update("user-1", "new")
        self.assertEqual(cache["user-1"], "old")


if __name__ == "__main__":
    unittest.main()
